/*
 * A393807  Palindromes that have only one smallest digit (strict minimum).
 * https://oeis.org/A393807
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the n-th odd‑length palindrome (including single digits)
 *            whose center digit is strictly smaller than every other digit
 *            (i.e. the smallest digit occurs only once). The sequence is
 *            generated by enumerating palindromes in increasing order of
 *            length and lexicographically within each length: fo...
 * Range:     u8 n <= 13, u16 n <= 185, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Compute the n-th term of OEIS A393807. */
seq_t a(idx_t n)
{
    /* terms 1..10 are single digits 0..9 */
    if (n <= 10)
        return (seq_t)(n - 1);

    /* pre‑compute powers of 10 in seq_t */
    static seq_t pow10[20];
    static int pow10_done = 0;
    if (!pow10_done) {
        pow10[0] = 1;
        for (int i = 1; i < 20; ++i)
            pow10[i] = pow10[i - 1] * (seq_t)10;
        pow10_done = 1;
    }

    /* count remaining terms after the first 10 */
    idx_t rem = n - 10;
    for (int k = 1; ; ++k) {          /* k = (length-1)/2, length=2k+1 */
        idx_t start = 1;
        for (int i = 1; i < k; ++i)   /* start = 10^(k-1) */
            start *= 10;
        idx_t end = start * 10 - 1;     /* end = 10^k - 1 */

        seq_t pow10_k = pow10[k];
        seq_t pow10_k_plus1 = pow10[k + 1];

        for (idx_t left = start; left <= end; ++left) {
            /* find minimum digit of the left half */
            int min_d = 9;
            idx_t tmp_left = left;
            while (tmp_left > 0) {
                int d = tmp_left % 10;
                if (d < min_d) min_d = d;
                tmp_left /= 10;
            }
            if (min_d == 0)              /* no center digit possible */
                continue;

            /* reverse of the left half */
            seq_t rev = 0;
            idx_t rev_tmp = left;
            for (int i = 0; i < k; ++i) {
                rev = rev * (seq_t)10 + (seq_t)(rev_tmp % 10);
                rev_tmp /= 10;
            }

            for (int c = 0; c < min_d; ++c) {
                /* build full palindrome: left + center + rev */
                seq_t value = (seq_t)left * pow10_k_plus1
                           + (seq_t)c * pow10_k
                           + rev;
                if (--rem == 0)
                    return value;
            }
        }
    }

    /* unreachable */
    return 0;
}
